package no.ntnu.tdt4250.rango.gamemode.dsl.generator;

import java.io.File;

import org.eclipse.emf.common.util.URI;
import org.eclipse.emf.ecore.resource.Resource;
import org.eclipse.emf.ecore.resource.ResourceSet;
import org.eclipse.xtext.validation.Issue;

import com.google.inject.Inject;
import com.google.inject.Injector;
import com.google.inject.Provider;

import no.ntnu.tdt4250.rango.gamemode.dsl.RangoModeStandaloneSetup;

/**
 * Command-line generator: derives a product of the Rango Unchained product line from an edition model.
 *
 * <pre>
 * java ... no.ntnu.tdt4250.rango.gamemode.dsl.generator.Main &lt;edition.rango&gt; &lt;game folder&gt;
 * </pre>
 *
 * The model is validated with all constraints of the metamodel and the checks of the DSL. If it has
 * errors, nothing is generated and the exit code is 1 (2 for wrong arguments). See {@link GameGeneration}.
 */
public class Main {

	/**
	 * When this system property is true (as in the Maven build, which runs the generator inside its own
	 * JVM), failures are reported by an exception instead of an exit code.
	 */
	public static final String NO_EXIT = "rango.generator.noExit";

	public static void main(String[] args) {
		boolean exit = !Boolean.getBoolean(NO_EXIT);
		if (args.length != 2) {
			System.err.println("Usage: Main <edition.rango> <game folder>");
			if (exit) {
				System.exit(2);
			}
			throw new IllegalArgumentException("Usage: Main <edition.rango> <game folder>");
		}
		Injector injector = new RangoModeStandaloneSetup().createInjectorAndDoEMFRegistration();
		Main main = injector.getInstance(Main.class);
		boolean generated = main.runGenerator(args[0], args[1]);
		if (exit) {
			System.exit(generated ? 0 : 1);
		} else if (!generated) {
			throw new IllegalStateException("No game modes generated from " + args[0]);
		}
	}

	@Inject
	private Provider<ResourceSet> resourceSetProvider;

	@Inject
	private GameGeneration generation;

	/**
	 * @return whether the model was valid and the game modes were generated
	 */
	public boolean runGenerator(String model, String gameFolder) {
		File modelFile = new File(model).getAbsoluteFile();
		if (!modelFile.isFile()) {
			System.err.println("No such model: " + modelFile);
			return false;
		}
		ResourceSet set = resourceSetProvider.get();
		Resource resource = set.getResource(URI.createFileURI(modelFile.getPath()), true);

		GameGeneration.Outcome outcome = generation.generate(resource, new File(gameFolder).getAbsoluteFile());
		for (Issue issue : outcome.issues()) {
			System.err.println(issue.getSeverity() + " " + modelFile.getName() + ":" + issue.getLineNumber() + ": "
					+ issue.getMessage());
		}
		(outcome.generated() ? System.out : System.err).println(outcome.message());
		return outcome.generated();
	}
}
